77	    protected <M extends Message> CompletableFuture<Void> updateOneKeyAsync(@Nonnull final FDBIndexableRecord<M> savedRecord,
78	                                                                      final boolean remove,
79	                                                                      @Nonnull final IndexEntry indexEntry) {
80	        if (state.index.isUnique()) {
81	            throw new MetaDataException("index type does not support unique indexes")
82	                    .addLogInfo(LogMessageKeys.INDEX_TYPE, state.index.getType())
83	                    .addLogInfo(LogMessageKeys.INDEX_NAME, state.index.getName());
84	        }
85	        final Tuple valueKey = indexEntry.getKey();
86	        final Tuple value = indexEntry.getValue();
87	        final long startTime = System.nanoTime();
88	        final Tuple entryKey = indexEntryKey(valueKey, savedRecord.getPrimaryKey());
89	        final boolean hasIncomplete = entryKey.hasIncompleteVersionstamp();
90	        final byte[] keyBytes;
91	        if (hasIncomplete) {
92	            keyBytes = state.indexSubspace.packWithVersionstamp(entryKey);
93	        } else {
94	            keyBytes = state.indexSubspace.pack(entryKey);
95	        }
96	        if (remove) {
97	            if (hasIncomplete) {
98	                state.context.removeVersionMutation(keyBytes);
99	            } else {
100	                state.transaction.clear(state.indexSubspace.pack(entryKey));
101	            }
102	            if (state.store.getTimer() != null) {
103	                state.store.getTimer().recordSinceNanoTime(FDBStoreTimer.Events.DELETE_INDEX_ENTRY, startTime);
104	            }
105	        } else {
106	            final byte[] valueBytes = value.pack();
107	            checkKeyValueSizes(savedRecord, valueKey, value, keyBytes, valueBytes);
108	            if (hasIncomplete) {
109	                state.context.addVersionMutation(MutationType.SET_VERSIONSTAMPED_KEY, keyBytes, valueBytes);
110	            } else {
111	                state.transaction.set(keyBytes, valueBytes);
112	            }
113	            if (state.store.getTimer() != null) {
114	                state.store.getTimer().recordSinceNanoTime(FDBStoreTimer.Events.SAVE_INDEX_ENTRY, startTime);
115	            }
116	        }
117	        return AsyncUtil.DONE;
118	    }
